<script setup>
import {previewMode} from "../preview/mode"
import SocialLinks from './SocialLinks.vue'
import LmsIdentityCard from './LmsIdentityCard.vue'
import PrivateContact from './PrivateContact.vue'
import EducationLevelSelect from './EducationLevelSelect.vue'
import LanguageSelect from './LanguageSelect.vue'
const subjects=['Mathematics','Science','English','Sinhala','Tamil','ICT','Business Studies','Accounting','Economics','Biology','Physics','Chemistry','History','Geography','Commerce','Computer Science','Engineering','Art','Music','Law']
function suggestSubject(subject){const parts=form.value.curriculum.split(',').map(s=>s.trim()).filter(Boolean);if(!parts.includes(subject)&&[...parts,subject].join(', ').length<=150)form.value.curriculum=[...parts,subject].join(', ')}
import SocialIcon from './SocialIcon.vue'
import {socialNetworks} from './socials.js'
import {ref} from 'vue'
import {call,uploadImage} from '../service'
import {safeLink} from '../rules'
import {upload as uploadRequest} from '../native/client'
const props=defineProps({member:Object}),emit=defineEmits(['saved','navigate'])
const error=ref(''),busy=ref(false),existing=ref(null),phoneVerified=ref(null),saved=ref(false),imageNote=ref('')
const form=ref({username:'',display_name:props.member.full_name,kind:props.member.role==='Admin'?'Institute':props.member.role==='Student'?'Student':'Teacher',country:'Sri Lanka',bio:'',tagline:'',qualifications:'',curriculum:'',grades:'',languages:'English',socials:{facebook:'',instagram:'',twitter:'',youtube:'',linkedin:'',tiktok:''},is_school:false})
async function load(){try{const response=await call('me',{},'profiles');phoneVerified.value=!!response.phone_verified;const d=response.profile;if(d){existing.value=d;Object.assign(form.value,d);if(typeof d.socials==='string')form.value.socials=JSON.parse(d.socials)}}catch(e){error.value=e.message}}
async function save(){busy.value=true;error.value='';saved.value=false;try{if(form.value.kind==='Student')form.value.socials={};for(const url of Object.values(form.value.socials||{}))if(url&&!safeLink(url))throw Error('Use a valid HTTPS social link.');await call('save_profile',{data:form.value},'profiles');await load();saved.value=true;emit('saved')}catch(e){error.value=e.message}finally{busy.value=false}}
async function imageUpload(event,kind){const file=event.target.files[0];if(!file||busy.value)return;busy.value=true;error.value='';imageNote.value='';saved.value=false;try{if(file.size>5*1024*1024)throw Error('Choose an image no larger than 5 MB.');if(previewMode)throw Error('Connect to the local server to save your photo.');const body=new FormData();body.append('kind',kind);body.append('file',file);const result=await uploadRequest('profiles','upload_image',body);const check=await call('me',{},'profiles');if(!result?.url||check.profile?.[kind]!==result.url)throw Error('The image could not be verified as saved. Please retry.');form.value[kind]=result.url;existing.value=check.profile;imageNote.value='Photo uploaded and saved.';emit('saved')}catch(e){error.value=e.message}finally{busy.value=false;event.target.value=''}}

load()
</script>
<template><form class="panel public-profile-editor" @submit.prevent="save"><header class="profile-intro"><span class="eyebrow">YOUR PUBLIC PROFILE</span><h1>Make it yours</h1><p>Start with your details. Add a photo, teaching information and social links whenever you’re ready.</p></header><div v-if="member.role!=='Student'" class="profile-cover-preview"><img v-if="form.cover_image" :src="form.cover_image" alt="Your profile cover"><div class="profile-photo-preview"><img v-if="form.profile_image" :src="form.profile_image" alt="Your profile picture"><span v-else>{{form.display_name?.slice(0,1)}}</span></div></div><p v-if="member.role!=='Student'&&existing?.lms_id" class="profile-permanent-id">{{existing.lms_id}}</p><SocialLinks v-if="member.role!=='Student'" :profile="form"/><details class="profile-section"><summary>Your digital ID</summary><LmsIdentityCard :profile="existing ? {...existing,profile_image:form.profile_image||existing.profile_image} : null"/></details><h2>{{member.role==='Student'?'Your student profile':'A profile that feels like you.'}}</h2><button v-if="member.role==='Teacher'" type="button" class="button subtle" @click="emit('navigate','papers')">My papers & assessments →</button><details v-if="existing" class="profile-section"><summary>Photos & cover</summary><p v-if="imageNote" role="status">{{imageNote}}</p><p v-if="error" role="alert" class="profile-save-error">{{error}}</p><label v-if="member.role!=='Student'">Cover photo · 8:3 · up to 5 MB<input type="file" accept="image/jpeg,image/png,image/webp" :disabled="busy" @change="imageUpload($event,'cover_image')"></label><label>{{member.role==='Student'?'Student ID photo · square · up to 5 MB':'Profile photo · square · up to 5 MB'}}<input type="file" accept="image/jpeg,image/png,image/webp" :disabled="busy" @change="imageUpload($event,'profile_image')"></label><p v-if="member.role==='Student'">Upload a clear photo for your student ID. Your photo saves immediately after upload.</p><p v-else>Images are centre-cropped and compressed. They are visible to people viewing your public profile. Photos save immediately after upload.</p></details><p>Your username stays yours. Changes to your name, country or account identity need review. You can update your bio anytime.<span v-if="form.kind!=='Student'"> Icons here preview your entries. Social links appear publicly only after a successful save.</span></p><p v-if="error" role="alert">{{error}}</p><details open class="profile-section"><summary>1. Basic details</summary><div class="profile-fields"><label>Display name<input v-model="form.display_name" required maxlength="120"></label><label>Tagline<input v-model="form.tagline" maxlength="120" placeholder="For better education for all"></label><label v-if="form.kind==='Teacher'">Qualifications<input v-model="form.qualifications" maxlength="240" placeholder="BSc, BEd, MSc…"></label><label>Unique username<input v-model="form.username" :readonly="!!existing" required pattern="[a-z][a-z0-9_]{2,29}" maxlength="30"></label><label>Country<input v-model="form.country" required maxlength="80"></label><label>About you<textarea v-model="form.bio" maxlength="1000"></textarea></label></div></details><details class="profile-section"><summary>{{member.role==='Student'?'2. Education':'2. Teaching & learning'}}</summary><template v-if="form.kind!=='Student'"><label>Curriculum / subjects<input v-model="form.curriculum" maxlength="150" list="profile-subjects" placeholder="Type a subject or choose a suggestion"></label><datalist id="profile-subjects"><option v-for="subject in subjects" :value="subject"/></datalist><div class="subject-suggestions" aria-label="Suggested subjects"><button v-for="subject in subjects.slice(0,10)" type="button" class="button subtle small" @click="suggestSubject(subject)">{{subject}} +</button></div><p>Choose several subjects, separated by commas. You can add your own.</p></template><EducationLevelSelect v-model="form.grades"/><LanguageSelect v-model="form.languages"/></details><details v-if="form.kind==='Teacher'||form.kind==='Institute'" class="provider-social-editor profile-section"><summary>3. Social links · optional</summary><p>Add your official social profiles. All six icons appear on your profile. Add a link to make its icon clickable.</p><label v-for="(name,key) in socialNetworks" :key="key"><span class="social-field-name"><SocialIcon :network="key"/>{{name}}</span><input v-model="form.socials[key]" type="url" maxlength="500" placeholder="https://…"></label></details><label v-if="form.kind==='Institute'" class="checkbox-label"><input v-model="form.is_school" type="checkbox">School workspace · platform billing only, no student class checkout</label><p v-if="phoneVerified===false" role="status">Verify your mobile number in the contact section below before saving your profile.</p><p v-if="error" role="alert" class="profile-save-error">Not saved: {{error}}</p><p v-if="saved" role="status">Profile saved successfully.</p><button class="button primary" :disabled="busy">{{busy?'Saving…':'Save profile'}}</button></form><section class="profile-contact-section"><h2>Contact & connected services</h2><p>Verify your phone here before saving profile details. Connect services only when you need them.</p><PrivateContact :member="member"/></section></template>
<style>.public-profile-editor{padding:30px;margin:24px 0;max-width:760px}.public-profile-editor label{display:flex;flex-direction:column;gap:10px;margin:18px 0;font-size:12px}.public-profile-editor :is(input,textarea){padding:13px;background:var(--student-card);color:var(--student-ink);border:1px solid var(--student-border);border-radius:12px}.public-profile-editor .checkbox-label{flex-direction:row}.public-profile-editor p{margin:15px 0;font-size:12px}</style>

<style>.profile-cover-preview{position:relative;aspect-ratio:8/3;background:linear-gradient(125deg,rgb(108 106 238 / 12%),rgb(108 106 238 / 18%));border-radius:18px;margin-bottom:68px}.profile-cover-preview>img{width:100%;height:100%;object-fit:cover;border-radius:18px}.profile-photo-preview{width:104px;height:104px;border:5px solid var(--student-card,#fff);border-radius:50%;position:absolute;bottom:-40px;left:25px;background:#6C6AEE;display:grid;place-items:center;font-size:35px;color:white;overflow:hidden}.profile-photo-preview img{width:100%;height:100%;object-fit:cover}</style>

<style>.provider-social-editor{border-top:1px solid var(--student-border);padding-top:24px;margin-top:24px}.public-profile-editor .social-field-name{display:flex;align-items:center;gap:10px}.social-field-name svg{width:19px;height:19px;flex-shrink:0}.public-profile-editor>.provider-social-links{justify-content:flex-end;margin-top:-48px;margin-bottom:30px}</style>
<style>.subject-suggestions{display:flex;flex-wrap:wrap;gap:8px}.subject-suggestions button{font-size:11px}</style>

<style>.public-profile-editor>.profile-permanent-id{margin:-20px 0 26px 15px;font-size:11px;font-weight:700;letter-spacing:.5px;color:var(--brand,#63339a)}.public-profile-editor>.provider-social-links{margin-top:0}.public-profile-editor>.lms-identity h2{color:#fff}.public-profile-editor .lms-identity p{margin:0 0 14px;font-size:11px}</style>

<style>.public-profile-editor{max-width:960px;margin:0 auto;padding:28px!important}.profile-intro{margin-bottom:24px}.profile-intro h1{margin:8px 0}.profile-intro p{line-height:1.7;max-width:620px}.public-profile-editor .profile-cover-preview{max-height:220px;margin-bottom:52px}.profile-section{border:1px solid var(--line,#e5deec);border-radius:14px;padding:18px;margin:20px 0}.profile-section>summary{cursor:pointer;font-size:16px;font-weight:650;padding:4px}.profile-section[open]>summary{margin-bottom:20px}.profile-fields{display:grid;grid-template-columns:1fr 1fr;gap:16px}.profile-fields label:has(textarea){grid-column:1/-1}.public-profile-editor label{margin-bottom:14px}.profile-contact-section{max-width:960px;margin:30px auto}.profile-contact-section>p{margin:12px 0 20px;line-height:1.7}.profile-save-error{color:#a92842}.profile-section input[type=file]{max-width:100%}@media(max-width:600px){.profile-fields{grid-template-columns:1fr}.public-profile-editor{padding:18px!important}.profile-section{padding:14px}}</style>
